import{_ as a,c as e,a0 as t,o as r}from"./chunks/framework.p2VkXzrt.js";const m=JSON.parse('{"title":"孩子-纪伯伦","description":"","frontmatter":{},"headers":[],"relativePath":"哲思_人文_社科/箴言/长文/孩子-纪伯伦.md","filePath":"哲思_人文_社科/箴言/长文/孩子-纪伯伦.md","lastUpdated":1733761377000}'),o={name:"哲思_人文_社科/箴言/长文/孩子-纪伯伦.md"};function _(s,p,n,d,c,i){return r(),e("div",null,p[0]||(p[0]=[t('<h1 id="孩子-纪伯伦" tabindex="-1">孩子-纪伯伦 <a class="header-anchor" href="#孩子-纪伯伦" aria-label="Permalink to &quot;孩子-纪伯伦&quot;">​</a></h1><p>你的孩子，并不是你的孩子</p><p>他们是由生命本身的渴望而诞生的孩子</p><p>他们借助你来到这世界，却非因你而来</p><p>他们在你身旁，却并不属于你</p><p>你可以给予他们的是你的爱，而不是你的想法 因为他们有自己的思想</p><p>你可以庇护的是他们的身体，而不是他们的灵魂</p><p>因为他们的灵魂属于明天，属于你做梦也无法到达的明天</p><p>你可以拼尽全力，变得像他们一样，却不要让他们变得和你一样</p><p>因为生命不会后退，也不在过去停留。你是弓，儿女是从你那里射出的箭。</p><p>弓箭手望着未来之路上的箭靶，他用尽力气将弓拉开，使他的箭射得又快又远。</p><p>怀着快乐的心情，在弓箭手的手中弯曲吧，因为他爱一路飞翔的箭，也爱无比稳定的弓。</p><p>——纪伯伦《孩子》</p>',13)]))}const f=a(o,[["render",_]]);export{m as __pageData,f as default};
